require_once __DIR__ . '/includes/functions.php';
$pageTitle = 'Coastal Monitoring Map';
$activePage = 'map';
require __DIR__ . '/includes/header.php';
?>
<section class="page-hero"><div class="container"><span class="eyebrow eyebrow-light">A COMMUNITY VIEW OF OUR SHARED COAST</span><h1>Coastal monitoring map</h1><p>Explore public incident reports in Marinduque. Reporter contact details and precise identities are never shown on the map.</p></div></section>
<section class="content-section"><div class="container"><div class="surface-card">
    <div class="row g-3 align-items-end mb-3"><div class="col-md-4"><label class="form-label" for="map-category">Incident category</label><select class="form-select" id="map-category"><option value="">All categories</option><?php foreach (report_categories() as $category): ?><option><?= e($category) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label" for="map-status">Report status</label><select class="form-select" id="map-status"><option value="">All active statuses</option><?php foreach (array_slice(report_statuses(), 0, 4) as $status): ?><option><?= e($status) ?></option><?php endforeach; ?></select></div><div class="col-md-5"><label class="form-label" for="map-search">Search area</label><div class="input-group"><input class="form-control" id="map-search" placeholder="Barangay or place name"><button class="btn btn-outline-primary" id="map-search-button" type="button">Find</button></div></div></div>
    <div id="coastal-map" class="map-box"></div><div class="d-flex justify-content-between gap-3 flex-wrap mt-3"><div class="map-legend"><span><i class="fa-solid fa-location-dot marker-blue"></i> Received / under review</span><span><i class="fa-solid fa-location-dot marker-orange"></i> In progress</span><span><i class="fa-solid fa-location-dot marker-green"></i> Resolved</span></div><small class="help-text" id="map-count">Loading public locations…</small></div>
</div></div></section>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
document.addEventListener('DOMContentLoaded',()=>{const map=L.map('coastal-map').setView([13.45,121.95],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const markers=L.layerGroup().addTo(map);const category=document.getElementById('map-category'),status=document.getElementById('map-status'),count=document.getElementById('map-count');function safe(v){const d=document.createElement('div');d.textContent=v??'';return d.innerHTML}async function load(){count.textContent='Loading public locations…';markers.clearLayers();const q=new URLSearchParams({category:category.value,status:status.value});try{const r=await fetch('actions/map-data.php?'+q);if(!r.ok)throw new Error('Map data request failed');const data=await r.json();data.forEach(item=>{const color=item.status==='Resolved'?'#33a278':item.status==='In Progress'?'#e2a72e':'#087db5';const icon=L.divIcon({className:'custom-marker',html:'<i style="color:'+color+';font-size:27px;text-shadow:0 2px 4px #fff" class="fa-solid fa-location-dot"></i>',iconSize:[25,30],iconAnchor:[12,29]});L.marker([Number(item.latitude),Number(item.longitude)],{icon}).bindPopup('<b>'+safe(item.reference_number)+'</b><br>'+safe(item.category)+'<br>'+safe(item.location)+', '+safe(item.barangay)+'<br>'+safe(item.incident_date)+' · '+safe(item.status)).addTo(markers)});count.textContent=data.length+' public location'+(data.length===1?'':'s');}catch(e){count.textContent='Could not load incident locations. Please try again.'}}category.addEventListener('change',load);status.addEventListener('change',load);document.getElementById('map-search-button').addEventListener('click',async()=>{const value=document.getElementById('map-search').value.trim();if(!value)return;try{const response=await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+encodeURIComponent(value+', Marinduque, Philippines'));const result=(await response.json())[0];if(result)map.setView([Number(result.lat),Number(result.lon)],13);else alert('No matching place was found.')}catch(e){alert('Place search is unavailable right now.')}});load();setTimeout(()=>map.invalidateSize(),150)});
</script>
